dateien.style.css:
body {
  font-family: sans-serif;
  background: #f0f0f0;
  text-align: center;
}

h1 {
  color: navy;
}

button {
  font-size: 2rem;
  padding: 10px 20px;
}

dateien.script.js:
let zaehler = 0;
const anzeige = document.getElementById('anzeige');
const plus = document.getElementById('plus');

plus.addEventListener('click', () => {
  zaehler++;
  anzeige.textContent = zaehler;
  anzeige.style.color = 'yellow';
});
